          d.dispatchEvent(new Event("DOMContentLoaded"));
          window.setTimeout(ensureWisp, 0);
        };
      }
      b.appendChild(s);
    });
  }

  function ensureWisp() {
    var proxy = self.proxy;
    if (!proxy || !proxy.initReady || typeof proxy.ping !== "function" ||
        typeof proxy.swapWispServer !== "function") {
      window.setTimeout(ensureWisp, 250);
      return;
    }

    proxy.initReady.then(function() {
      var candidates = [
        proxy.wispUrl,
        "wss://daydreamx.pro/wisp/",
        "wss://wisp.mercurywork.shop/"
      ];
      var index = 0;

      function checkNext() {
        if (index >= candidates.length) return;
        var url = candidates[index++];
        if (!url) return checkNext();
        return proxy.ping(url).then(function(result) {
          if (!result || !result.online) return checkNext();
          var updated = proxy.wispUrl === url
            ? Promise.resolve()
            : proxy.swapWispServer(url);
          return updated.then(function() {
            var frames = document.querySelectorAll("iframe");
            Array.prototype.forEach.call(frames, function(frame) {
              try {
                var latency = frame.contentDocument &&
                  frame.contentDocument.getElementById("latency");
                if (!latency) return;
                latency.textContent = result.ping + "ms";
                latency.classList.remove("text-red-500");
                latency.classList.remove("text-[var(--text)]/80");
                latency.classList.add("text-green-500");
              } catch (e) {}
            });
          });
        }, checkNext);
      }

      return checkNext();
    });
  }

  // Load non-module deps first, then modules after all finish
  var srcs = ["./data/bundle.js","./data/config.js","./assets/config.js","./assets/all.js","./assets/topography.js"];
  var pending = srcs.length;
  function done() { if (--pending === 0) loadModules(); }
  srcs.forEach(function(u) {
    var s = d.createElementNS(ns, "script");
    s.setAttribute("src", u);
    s.async = false;
    s.onload = done;
    s.onerror = done;
    b.appendChild(s);
  });
